  insert into public.brands (name, website, description, country, status) values ('GoodDot', 'https://gooddot.in', 'Indian plant-based meat brand (GoodDot, FSSAI certified) selling meat-alternative products direct to consumers. Its affiliate program is explicitly built for creators: recipe creators, fitness influencers, vegan bloggers, mom/family creators, lifestyle YouTubers, cookbook authors, nutritionists and food reviewers, with free Reels templates, recipe scripts and product photos provided.', 'India', 'published') returning id into bid;
