  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'GoAffPro', 10, 'Commission cap: UNCAPPED — stated in the program terms (see evidence). Creator saturation: unknown (see evidence). Rate as reported by https://gooddot.in/pages/affiliate-program.', 'https://gooddot.in/pages/affiliate-program', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'GoodDot Plant-Based Affiliate Program', 'https://gooddot.in/pages/affiliate-program', 'https://gooddot.in/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gooddot.in/pages/affiliate-program', 'official_site', 'affiliate', 'Own affiliate page: 10% commission on every order placed using your code, ''with no cap on earnings''; FAQ ''Is there a cap on what I can earn?'' — ''None. Top affiliates clear Rs 3,00,000+ in a single month. Earnings scale directly with the value you create.'' 30-day cookie, real-time dashboard via GoAffPro, monthly UPI payouts above a Rs 500 minimum, auto-approved signup, no minimum follower count.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gooddot.in/pages/affiliate-program', 'official_site', 'ugc_collab', 'Page states ''Join 200+ creators earning with GoodDot'' and lists suitable creator types (recipe creators, fitness influencers, vegan/vegetarian bloggers, mom & family creators, lifestyle YouTubers, cookbook authors, nutritionists, food reviewers); active affiliates receive a free monthly product hamper. The 200+ figure is a few-hundred count, so saturation is recorded as unknown under the strict absolute-terms rule.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://gooddot.in/pages/affiliate-program', 'official_site', 'general', 'Brand describes itself on the program page as India''s #1 plant-based meat brand, FSSAI certified, featured in Forbes, Fortune and Economic Times.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 17, 6, 9, 4, '{"compensation": "Published 10% on every order AND verified uncapped \u2014 own FAQ answers the cap question with ''None.''", "contact_access": "No published email on the program page; support runs through the affiliate dashboard and a WhatsApp group after joining.", "credibility": "FSSAI certified brand; own page cites Forbes, Fortune and Economic Times features.", "niche_fit": "Plant-based meat is a strong food-creator niche; program explicitly targets recipe, fitness and vegan creators.", "opportunity_availability": "Auto-approved in 30 seconds, no paperwork, no waiting list, no minimum follower count.", "ugc_evidence": "Program is creator-first: free Reels templates, recipe scripts, product photos, monthly product hampers for active affiliates."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('CakeFlix', 'https://www.cakeflix.com', 'UK online cake-decorating school founded by Paul Bradford, with 900+ video courses (1,000+ hours of tuition) sold as individual tutorials and memberships. Its long-running affiliate program pays commission on tutorial and membership sales referred by blogs, Facebook pages and other food/baking sites.', 'United Kingdom', 'published') returning id into bid;
