  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'CakeFlix Affiliate Program', 'https://www.cakeflix.com/become-an-affiliate/', 'https://www.cakeflix.com/become-an-affiliate/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cakeflix.com/become-an-affiliate/', 'official_site', 'affiliate', 'Own affiliate page: 30% commission on individual tutorial sales and 30% of the initial membership fee (50% for guest tutors selling their own tutorials); ''How much can I expect to make? ... There is no cap on the amount you can earn, meaning, whether your link achieves one sale or 10,000 sales, you will receive commission for each of those sales.'' 30-day cookie, monthly payouts at a GBP 50 threshold, applications individually reviewed within 72 hours.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.cakeflix.com/become-an-affiliate/', 'official_site', 'ugc_collab', 'Program welcomes everyone from ''a small Facebook page or the biggest site on the internet''; partners get banners, ad copy and collaborative blog/YouTube promotion. Page frames the audience as websites/blogs with significant traffic, so it is content-site oriented rather than a pure short-form creator program.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 19, 7, 7, 4, '{"compensation": "30% on tutorials and memberships AND verified uncapped, stated explicitly on the brand''s own page.", "contact_access": "Contact is via the site''s affiliate contact route (email address is masked in page text); applications reviewed within 72 hours.", "credibility": "Established school: 900+ courses, founder has made cakes for royalty and celebrities per the program page.", "niche_fit": "Cake decorating is a focused food niche with a large tutorial-buying audience; narrower than general food.", "opportunity_availability": "Free to join but individually reviewed; page speaks to sites with significant traffic, so approval is not automatic.", "ugc_evidence": "Open to bloggers and Facebook pages of any size with banners, ad examples and partner blog/YouTube collaborations."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Wildly Organic', 'https://wildlyorganic.com', 'US organic foods brand (the online store of Wilderness Family Naturals, northern Minnesota) selling coconut oil, cacao, nuts, superfoods and body care it prepares and packages in its own US facilities. Its affiliate program, running on Affiliatly, is aimed at bloggers and social media promoters of natural foods.', 'United States', 'published') returning id into bid;
