  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Wildly Organic Affiliate Program', 'https://wildlyorganic.com/pages/affiliate-program', 'https://wildlyorganic.com/pages/affiliate-program', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://wildlyorganic.com/pages/affiliate-program', 'official_site', 'affiliate', 'Own affiliate page: ''From the start, you''ll earn 10% of completed orders. It''s possible to earn up to 20%!'' 30-day cookie, payouts once $50 minimum commission is earned, free to join; the page''s ''Login or Join Now!'' link routes to Affiliatly. No cap statement is published, so the cap is recorded as unknown. Contact shown on the page: help@wildlyorganic.com, +1 (218) 226-3985.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://wildlyorganic.com/pages/affiliate-program', 'official_site', 'general', 'Brand states it has operated for 16 years, prepares and packages nearly everything it sells in its own facilities in the USA, and lets affiliates attach their affiliate ID to the blog''s evergreen content as well as their own channels.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 13, 14, 12, 9, 4, '{"compensation": "10% starting rate rising to a possible 20%; no published cap statement, so cap honestly unknown.", "contact_access": "Published support email and phone number directly on the affiliate page.", "credibility": "16-year operating history and own US production facilities, per the brand''s own page.", "niche_fit": "Organic pantry staples and superfoods fit food, recipe and natural-living creators well.", "opportunity_availability": "Free to join through the Affiliatly portal linked from the program page.", "ugc_evidence": "Program is pitched at bloggers and social promoters with promotional tools provided; no dedicated creator perks beyond that."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Sun Home Saunas', 'https://sunhomesaunas.com', 'US home-wellness equipment brand selling infrared and traditional home saunas, cold plunges, infrared blankets and red light therapy products. Its affiliate program, run on Impact, explicitly recruits bloggers, influencers and content creators in the fitness, wellness, biohacking and nutrition space.', 'United States', 'published') returning id into bid;
