  insert into public.brand_contacts (brand_id, contact_type, email, contact_url, source_url, verification_status, last_verified_at) values (bid, 'partnerships', 'info@sunhomesaunas.com', null, 'https://sunhomesaunas.com/pages/become-an-affiliate', 'verified', now());
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Impact', 5, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://sunhomesaunas.com/pages/become-an-affiliate.', 'https://sunhomesaunas.com/pages/become-an-affiliate', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Sun Home Saunas Affiliate Program (Impact)', 'https://sunhomesaunas.com/pages/become-an-affiliate', 'https://sunhomesaunas.com/pages/become-an-affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://sunhomesaunas.com/pages/become-an-affiliate', 'official_site', 'affiliate', 'Own affiliate page: ''Are you a blogger, influencer, or content creator with a presence in the fitness/wellness/biohacking/nutrition space? ... you are welcome to join our affiliate program.'' Signup links route to Impact (app.impact.com); partners get tracking links and a unique promo code (requested via info@sunhomesaunas.com), are paid monthly by PayPal or Venmo, and product-for-content requests go to the same email. The page''s ''There are no limits!'' line refers to where links may be displayed, NOT to earnings, so the cap is recorded as unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliategraph.ai/programs/sun-home-saunas', 'affiliate_network', 'compensation', 'Network-listing aggregator reports Sun Home Saunas at a 5%-5.3% commission with Impact as the direct network (base 5% listed on Impact; also on Skimlinks/Connexity as sub-affiliate routes). The 5% Impact base rate is recorded; confirm current terms inside Impact before promoting.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 22, 16, 10, 12, 8, 4, '{"compensation": "Low 5% percentage but on very high-ticket products (saunas), so per-sale payouts can still be large; no cap statement published.", "contact_access": "Published partner email (info@sunhomesaunas.com) for promo codes, product requests and questions.", "credibility": "Established US wellness-equipment seller with a full affiliate FAQ on its own site.", "niche_fit": "Saunas, cold plunges and red light are core biohacking/wellness topics; filed under home as the products are home equipment.", "opportunity_availability": "Open application via Impact with brand approval; monthly payouts.", "ugc_evidence": "Own page directly invites bloggers, influencers and content creators and offers product for content on request."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Suji', 'https://www.trysuji.com', 'US fitness-tech brand (Lake Nona, Florida) making Suji, a smart targeted-compression / blood-flow-restriction training and recovery device used by professional sports teams and physical therapists. Its affiliate program on GoAffPro pays creators 10% on referred sales.', 'United States', 'published') returning id into bid;
