  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Suji Affiliate Program', 'https://www.trysuji.com/pages/become-a-suji-affiliate', 'https://www.trysuji.com/pages/become-a-suji-affiliate', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.trysuji.com/pages/become-a-suji-affiliate', 'official_site', 'affiliate', 'Own affiliate page: ''Earn 10% commission by sharing a product trusted by elite athletes, physical therapists, and thousands of active individuals.'' Apply buttons route to the brand''s GoAffPro portal (trysuji.goaffpro.com). The program targets fitness & wellness creators, physical therapists/trainers and active individuals, and provides creative assets, videos, photos and captions. No cap statement published, so cap is unknown.', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.trysuji.com/pages/become-a-suji-affiliate', 'official_site', 'general', 'Brand states its customers include 40% of American sports teams and hundreds of healthcare professionals, and its site reports a Men''s Health Tech Awards win for the device.', 'verified', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 16, 13, 6, 9, 4, '{"compensation": "Published 10% on every referred sale; no cap statement, so cap honestly unknown.", "contact_access": "No published email on the affiliate page; contact runs through the GoAffPro application.", "credibility": "Pro-team adoption claims and a Men''s Health Tech Award reported on the brand''s own site.", "niche_fit": "Smart BFR/recovery device sits squarely in fitness and recovery content.", "opportunity_availability": "Open application via GoAffPro with dashboard tracking.", "ugc_evidence": "Page explicitly recruits fitness & wellness creators and supplies creative assets and guidance."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Cowboy Colostrum', 'https://cowboycolostrum.com', 'US wellness brand selling premium grass-fed bovine colostrum supplements. Its affiliate program, run on Social Snowball with tiered commissions and automated monthly payouts, turns customers and micro-influencers into affiliates and drove $473K+ in affiliate revenue in its first seven months on the platform.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'wellness'), true);
  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Social Snowball', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://www.socialsnowball.io/post/success-stories-cowboy-colostrum.', null, 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Cowboy Colostrum Affiliate Program (Social Snowball)', null, 'https://www.socialsnowball.io/post/success-stories-cowboy-colostrum', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.socialsnowball.io/post/success-stories-cowboy-colostrum', 'listing', 'affiliate', 'Social Snowball case study of the brand''s own program: structured affiliate tiers with different commission levels by performance, automated monthly payouts via Tremendous, ''anyone can get a link'', heavy micro-influencer and customer participation, 1,725 affiliates onboarded and $473K+ in affiliate-driven revenue in seven months (top affiliate: 1,000+ referral orders). Commission percentages are set per tier and are not published, so the rate is recorded as null; the 1,725-affiliate count is neither ~100-scale nor 10,000-scale, so saturation is unknown.', 'publicly_reported', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.socialsnowball.io/post/success-stories-cowboy-colostrum', 'listing', 'ugc_collab', 'Case study quotes the brand''s Head of Partnerships (Taylor Fulton-Girgis) and describes product seeding to interested creators followed by personalized links/codes, monthly affiliate newsletters with marketing ideas, and Instagram content tracking — an actively managed creator program. The brand previously ran the program on Impact before moving to Social Snowball.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 26, 17, 9, 6, 9, 4, '{"compensation": "Tiered commissions exist but no percentage is published anywhere fetched, so the rate is honestly null.", "contact_access": "A named Head of Partnerships runs the program, but no public contact email was found on a fetched page.", "credibility": "Documented $473K+ affiliate revenue and 1,700+ affiliates in a named platform case study.", "niche_fit": "Colostrum is a high-demand wellness supplement category with strong creator interest.", "opportunity_availability": "Open, low-friction onboarding \u2014 ''anyone can get a link'' per the platform case study.", "ugc_evidence": "Program is built on micro-influencers and customers, with product seeding, content tracking and affiliate newsletters."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Ritual Zero Proof', 'https://www.ritualzeroproof.com', 'American non-alcoholic spirit alternatives brand (tequila, gin, whiskey and aperitif alternatives made with natural botanicals, no added sugar). Its affiliate program on Awin pays a base 5% revenue share with a 30-day cookie and targets cocktail, recipe and healthy-lifestyle creators.', 'United States', 'published') returning id into bid;
  insert into public.brand_categories (brand_id, category_id, is_primary) values (bid, (select id from public.categories where slug = 'food-drink'), true);
