  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Ritual Zero Proof Affiliate Program (Awin)', 'https://tbsmo.com/digital-marketing-services-nj/affiliate-marketing/affiliate-sign-up/ritual-zero-proof-affiliateprogram/', 'https://tbsmo.com/digital-marketing-services-nj/affiliate-marketing/affiliate-sign-up/ritual-zero-proof-affiliateprogram/', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://tbsmo.com/digital-marketing-services-nj/affiliate-marketing/affiliate-sign-up/ritual-zero-proof-affiliateprogram/', 'listing', 'affiliate', 'Program page from the brand''s affiliate management agency (Today''s Business): the Ritual Zero Proof affiliate program runs on Awin with a base 5% RevShare payout ''with opportunity for increase'', a 30-day cookie window, product-for-review and giveaway opportunities, and a dedicated account manager. US traffic only; the program actively seeks bloggers and influencers (cocktail enthusiasts, recipe influencers, health-conscious and parent creators). Affiliate team contact published on the page: affiliate@todaysbusines4.wpenginepowered.com. No cap statement, so cap is unknown.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 14, 10, 10, 8, 4, '{"compensation": "Base 5% revenue share with stated opportunity for increase; modest rate, no cap statement published.", "contact_access": "Published affiliate-team email and a dedicated account manager for the program.", "credibility": "Established category brand with a professionally managed network program.", "niche_fit": "Non-alcoholic spirits are a fast-growing drinks niche for cocktail and sober-curious creators.", "opportunity_availability": "Open application through Awin for US-traffic publishers.", "ugc_evidence": "Program page explicitly recruits bloggers and influencers and offers product for review and audience giveaways."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('Hapbee', 'https://hapbee.com', 'Canadian digital-wellness company (Hapbee Technologies, publicly traded on TSXV: HAPB) whose wearable Neckband and Sleep Pad use low-energy magnetic signals to deliver feelings such as focus, calm and sleepiness without ingestibles. In July 2025 it launched an integrated Affiliate and Ambassador Program open to creators of any size.', 'Canada', 'published') returning id into bid;
