  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'Hapbee Affiliate and Ambassador Program', 'https://www.hapbee.com/pages/collabs', 'https://www.hapbee.com/pages/collabs', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.hapbee.com/pages/collabs', 'official_site', 'affiliate', 'Own Brand Ambassadors page invites creators to ''Become a Hapbee Affiliate or Ambassador'', share authentic content about the Neckband and Sleep Pad, and earn affiliate rewards; it targets wellness, women''s health, lifestyle, family and tech voices ''from anywhere in the world''. No commission rate or cap statement is published on the page, so both are recorded honestly (rate null, cap unknown).', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.globenewswire.com/news-release/2025/07/29/3123510/0/en/Hapbee-Launches-Integrated-Affiliate-and-Ambassador-Program-to-Accelerate-Growth-and-Community-Expansion.html', 'listing', 'affiliate', 'Company press release (July 29, 2025) announcing the official launch of its technology-integrated Affiliate and Ambassador Program: open to all wellness advocates and creators ''regardless of the size of their social media following'', with real-time dashboards and payout visibility; signup via hapbee.com/pages/collabs. Endorsers named include Gary Brecka, Ben Greenfield and Dave Asprey.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 24, 16, 8, 6, 8, 5, '{"compensation": "Program pays affiliate rewards/commissions, but no rate is published on any fetched page, so the rate is honestly null.", "contact_access": "Application via the brand''s collabs page; no published partnerships email found.", "credibility": "Publicly traded company (TSXV: HAPB) with named high-profile users and a formal program launch.", "niche_fit": "Digital wellness wearable fits biohacking, sleep and focus content niches.", "opportunity_availability": "Open to creators of any follower size worldwide, per the launch release.", "ugc_evidence": "Dedicated affiliate/ambassador program built around creators sharing authentic everyday content."}'::jsonb);
  insert into public.brands (name, website, description, country, status) values ('BrainTap', 'https://braintap.com', 'Brain-fitness technology brand whose headset and app deliver guided light-and-sound sessions for sleep, stress and focus. Alongside its clinic-focused Professional Partner Program, BrainTap runs an Affiliate Program (on Post Affiliate Pro since November 2026) for coaches and creators who share a link and earn commission on referred sales.', null, 'published') returning id into bid;
