  insert into public.affiliate_programs (brand_id, network, commission_rate, commission_notes, application_url, status, last_checked_at) values (bid, 'Post Affiliate Pro', null, 'Commission cap: not stated in any published source found — needs review. Creator saturation: unknown (see evidence). Rate as reported by https://braintap.com/pages/become-a-braintap-partner.', 'https://braintap.com/pages/become-a-braintap-partner', 'needs_review', now());
  insert into public.opportunities (brand_id, title, application_url, source_url, status, opportunity_type) values (bid, 'BrainTap Affiliate Program', 'https://braintap.com/pages/become-a-braintap-partner', 'https://braintap.com/pages/become-a-braintap-partner', 'unverified', 'ugc');
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://braintap.com/pages/become-a-braintap-partner', 'official_site', 'affiliate', 'Own partner page offers three routes; the ''Affiliate'' route is described as: ''Share your link. Your audience buys directly from BrainTap and you earn commission'', best for ''Coaches, creators, anyone without a location'', no location needed. (The 30% commission figure on the same page belongs to the Professional Partner ''sell on commission'' route for practices, not the affiliate link program, so it is not recorded as the affiliate rate.)', 'verified', now());
  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://info.braintap.com/affiliate-program-update', 'affiliate_network', 'affiliate', 'Brand''s own program update: on November 1, 2026 the affiliate program moved from LeadDyno to Post Affiliate Pro (portal: affiliate.braintap.com); new affiliates apply, agree to terms, and are reviewed within 24-72 hours, with approval including confirmation of an active BrainTap subscription; commissions are paid via PayPal. The Post Affiliate Pro directory lists the program at 20-30% commission with a 60-day cookie and $100 minimum payout, but because BrainTap''s own pages do not publish the affiliate rate, the rate is recorded as null with the directory range documented here.', 'publicly_reported', now());
  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 23, 13, 12, 5, 6, 4, '{"compensation": "Directory lists 20-30%, but the brand does not publish the affiliate rate on its own pages, so the recorded rate is null.", "contact_access": "No published affiliate email on fetched pages; contact runs through the partner application/discovery-call route.", "credibility": "Established brand with a documented, recently migrated affiliate platform and published program terms.", "niche_fit": "Brain fitness, sleep and stress tech is a defined wellness niche with engaged audiences.", "opportunity_availability": "Application plus 24-72h review, and approval involves confirming an active BrainTap subscription, which narrows who can join.", "ugc_evidence": "A dedicated affiliate route explicitly names coaches and creators as its audience."}'::jsonb);
