  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://www.affiliatly.com/af-104281/affiliate.panel?mode=register', 'official_site', 'affiliate', 'Brand''s Affiliatly affiliate dashboard page: members receive a unique code and link offering a 10% discount on Tempdrop kits and earn a cash reward for every sale made using the code; Tempdrop seeks active affiliates who share its mission and asks affiliates to achieve at least 10 sales per year to remain in the program; applications are reviewed by the team.', 'verified', now());
