  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://help.frontpointsecurity.com/en/my-frontpoint-account/CAP_Termsandconditions', 'official_site', 'affiliate_program_terms', 'Frontpoint''s own Consumer Affiliate Program (CAP) agreement, effective July 29, 2024, confirms an in-house program that lets affiliates monetize websites, social media user-generated content, emails and apps with unique QR codes, URLs and referral codes; commission is paid on qualified actions (a new customer who signs a monitoring agreement, installs, activates and stays at least 30 days).', 'verified', now());
