  insert into public.brand_evidence (brand_id, source_url, source_type, evidence_type, evidence_summary, confidence, last_checked_at) values (bid, 'https://ui.awin.com/merchant-profile/17141?setLocale=en_US', 'affiliate_network', 'commission_rate_conflict', 'Rates conflict across sources: YuMOVE''s Awin programme profile lists commission from 6% for new customers and 1% for existing customers with a 30-day cookie, while Lasso lists 15% per sale. The Awin profile also names the managing agency (Summit Media) and its contacts (Lewis.walters@summitmedia.com, Gus.Beavis@summitmedia.com). Because the rates disagree, commission_rate is recorded as null.', 'publicly_reported', now());
