  insert into public.brand_scores (brand_id, niche_fit, ugc_evidence, compensation, contact_access, opportunity_availability, credibility, explanation) values (bid, 25, 16, 9, 9, 8, 3, '{"niche_fit": "Smart litter boxes, feeders and pet robots are exactly the gadget-pet crossover that drives pet-tech content.", "ugc_evidence": "The program is explicitly built for creators, with content guidelines, trackable links/codes and product seeding for fit audiences.", "compensation": "5% of net sales on main products; accessories are excluded, which trims the effective rate on mixed baskets.", "contact_access": "Structured on-page creator application (channels, region, audience scale) routed for team follow-up.", "opportunity_availability": "Open application, but approval is a manual fit review rather than instant enrollment.", "credibility": "Small, young DTC brand with a narrow public footprint compared with established pet names."}'::jsonb);
